"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6836"],{97819(e){e.exports=JSON.parse('{"id":"FIN-841","slug":"wire-transfer","term":"Wire Transfer","also_known_as":[],"difficulty":"Beginner","definition":"A wire transfer is an electronic transfer of money from one bank account to another, often used for large, urgent or international payments.","explanation":["Wire transfers move money directly between banks through secure networks. Domestic wire transfers often use a country\'s large-value payment system, while international wire transfers usually travel through the SWIFT network, which connects thousands of banks worldwide.","To send a wire transfer, the sender typically provides the recipient\'s name, bank details, account number and, for international transfers, a bank identifier code and sometimes an international bank account number.","For example, a buyer completing a house purchase might wire the deposit to the seller\'s solicitor or a title company, or a business might wire payment to an overseas supplier.","Wire transfers are generally fast and secure, with domestic transfers often arriving the same day and international ones taking one to several days. They usually involve fees, and international transfers may include currency conversion charges and fees charged by intermediary banks.","A key risk is that wire transfers are very difficult to reverse once sent. Scammers often target wire transfers, for example by sending fake emails with changed payment details. Verifying payment instructions by phone using a trusted number before sending large sums is an important precaution."],"note":"","total":1500,"prev":{"slug":"will","term":"Will"},"next":{"slug":"withdrawal-rate","term":"Withdrawal Rate"}}')}}]);